/* 🆕 管理コンソール「登録を完了」＝役割と必須3項目を1回で入れる（2026-09-14 ボス指示）。
   ⭐判定は staffRegMissing_ だけ。足りなければ**何も書かずに**足りない項目名を返す（画面が赤くする）。
   ⭐揃っていれば ①必須3項目を名簿へ ②setStaffRole_（関所の正本・シフト表の行・完了LINE）。
   ⚠️既に役割がある人には使わせない＝在籍者の役割の変更はカードの「属性」から（関所を掛けない既存の道）。 */
function adminCompleteStaffReg(userId, targetName, role, terms) {
  if (!isAdmin_(getStaffName(userId))) return { ok: false, error: '権限がありません' };
  targetName = String(targetName || '').trim();
  role = String(role || '').trim();
  if (!role) return { ok: false, missing: ['役割'], error: '役割を選んでください' };
  if (ADMIN_ROLES_.indexOf(role) < 0) return { ok: false, error: '不明な属性: ' + role };
  var sh = getOrOpenSS_().getSheetByName(STAFF_TAB);
  if (!sh) return { ok: false, error: 'スタッフマスタが見つかりません' };
  var rows = sh.getDataRange().getValues();
  var idx = -1;
  for (var i = 1; i < rows.length; i++) { if (String(rows[i][1]).trim() === targetName) { idx = i; break; } }
  if (idx < 0) return { ok: false, error: targetName + ' が見つかりません' };
  var cur = String(rows[idx][2] == null ? '' : rows[idx][2]).trim();
  if (cur) return { ok: false, error: targetName + ' は登録済みです（役割: ' + cur + '）。役割の変更はカードの「属性」から' };
  /* 画面から来た値を優先し、来なかった項目は名簿の今の値で見る */
  var merged = staffTermsOfRow_(rows[idx], getStaffTermCols_(sh, false));
  var w = {};
  STAFF_REQUIRED_TERMS_.forEach(function (h) {
    if (terms && Object.prototype.hasOwnProperty.call(terms, h)) {
      var v = String(terms[h] == null ? '' : terms[h]).trim();
      if (h === '基本時給' && staffWageYen_(v) > 0) v = String(staffWageYen_(v));   // 「５,０００円」→「5000」
      merged[h] = v; w[h] = v;
    }
  });
  var miss = staffRegMissing_(role, merged);
  if (miss.length) {
    return { ok: false, missing: miss, name: targetName,
             error: miss.join('・') + ' が未入力です（' + role + 'は 基本時給・基本バック・入店日 が必須です）' };
  }
  if (Object.keys(w).length) {
    var r1 = saveStaffTerms_(targetName, w);
    if (!r1 || !r1.ok) return r1 || { ok: false, error: '個別条件の保存に失敗しました' };
  }
  return setStaffRole_(targetName, role);
}
